function renderPfdLibrary(){const c=document.getElementById('wsContent');c.innerHTML=`<section class="pfd-library"><header class="pfd-lib-head"><div><h2>Diagrama PFD</h2><p>Biblioteca de símbolos y recreación inicial del proceso de pasteurización.</p></div><div class="pfd-lib-tools"><input id="pfdSymbolSearch" class="pfd-lib-search" placeholder="Buscar equipo o símbolo…" oninput="drawPfdSymbolLibrary()"></div></header><div class="pfd-lib-layout"><aside class="pfd-lib-sidebar"><div class="pfd-lib-sidebar-title">Biblioteca de símbolos</div><nav class="pfd-lib-tabs" id="pfdLibTabs"></nav><div class="pfd-symbol-grid" id="pfdSymbolGrid"></div></aside><main class="pfd-canvas-area" aria-label="Área de trabajo PFD"><div class="pfd-canvas-toolbar"><span>Diagrama de pasteurización · Vista inicial</span><div class="pfd-diagram-controls"><button type="button" onclick="pfdZoom(-1)" title="Alejar">−</button><span id="pfdZoomLabel">100%</span><button type="button" onclick="pfdZoom(1)" title="Acercar">＋</button><button type="button" onclick="pfdFit()" title="Ajustar al lienzo">Ajustar</button></div></div><div class="pfd-diagram-viewport" id="pfdDiagramViewport"><div class="pfd-diagram-frame" id="pfdDiagramFrame">${pfdPasteurSVG}</div></div></main><aside class="pfd-symbol-detail" id="pfdSymbolDetail"></aside></div><div class="pfd-lib-note">Etapa 1 · Diagrama de referencia recreado en vector para visualización. En la siguiente etapa se habilitará la edición individual de equipos, instrumentos, válvulas y corrientes.</div></section>`;drawPfdSymbolLibrary();pfdZoomLevel=1;pfdFit();}
let pfdZoomLevel=1;
function pfdZoom(dir){pfdZoomLevel=Math.max(.35,Math.min(2.5,pfdZoomLevel+(dir*.15)));const f=document.getElementById('pfdDiagramFrame');if(f)f.style.width=(pfdZoomLevel*100)+'%';const l=document.getElementById('pfdZoomLabel');if(l)l.textContent=Math.round(pfdZoomLevel*100)+'%'}
function pfdFit(){const v=document.getElementById('pfdDiagramViewport'),f=document.getElementById('pfdDiagramFrame');if(!v||!f)return;pfdZoomLevel=1;f.style.width='100%';const l=document.getElementById('pfdZoomLabel');if(l)l.textContent='100%';}
function drawPfdSymbolLibrary(){const tabs=document.getElementById('pfdLibTabs'),grid=document.getElementById('pfdSymbolGrid'),detail=document.getElementById('pfdSymbolDetail');if(!tabs||!grid||!detail)return;const cats=['Todos',...new Set(pfdSymbols.map(s=>s.cat))];tabs.innerHTML=cats.map(c=>`<button class="pfd-lib-tab ${pfdActiveCategory===c?'active':''}" onclick="pfdActiveCategory='${c}';drawPfdSymbolLibrary()">${c}${c==='Todos'?' ('+pfdSymbols.length+')':''}</button>`).join('');const q=(document.getElementById('pfdSymbolSearch')?.value||'').toLowerCase();const list=pfdSymbols.filter(s=>(pfdActiveCategory==='Todos'||s.cat===pfdActiveCategory)&&(s.name.toLowerCase().includes(q)||s.desc.toLowerCase().includes(q)||s.cat.toLowerCase().includes(q)));grid.innerHTML=list.map(s=>`<button class="pfd-symbol-card ${s.id===pfdSelectedSymbol?'selected':''}" onclick="pfdSelectedSymbol='${s.id}';drawPfdSymbolLibrary()">${pfdSvg(s)}<span>${s.name}</span></button>`).join('')||'<div class="pfd-lib-empty">No se encontraron símbolos.</div>';const selected=pfdSymbols.find(s=>s.id===pfdSelectedSymbol)||pfdSymbols[0];detail.innerHTML=`<div class="pfd-symbol-preview">${pfdSvg(selected,true)}</div><h3>${selected.name}</h3><p><strong>Categoria:</strong> ${selected.cat}</p><p>${selected.desc}</p><button class="btn" onclick="pfdSelectedSymbol='${selected.id}';drawPfdSymbolLibrary()">Seleccionar símbolo</button>`}
